export const title = "Will an In-Line Document Holder Fit Between Your Keyboard and Monitor?";
export const metaTitle = "Will an In-Line Document Holder Fit Your Desk?";
export const metaDescription = "Measure an in-line document holder with papers loaded, including keyboard access, screen visibility, base depth, and page changes.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-31";
